INSERT INTO `findings` VALUES (1,2,2,'2026-06',15,'unbalanced_ledger','critical','The ledger does not balance','For 2026-06, St Bede College Ashing reported debits of 12480000.00 against credits of 11980000.00 — a difference of 500000.00 across 394 journal entries. In double-entry bookkeeping this cannot happen by accident, so every figure in this month\'s report should be treated as unsafe until the institution explains it.','{\"total_debits\":\"12480000.00\",\"total_credits\":\"11980000.00\",\"difference\":\"500000.00\",\"journal_entry_count\":394,\"unposted_count\":0}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(2,2,2,'2026-07',16,'unbalanced_ledger','critical','The ledger does not balance','For 2026-07, St Bede College Ashing reported debits of 12480000.00 against credits of 11730000.00 — a difference of 750000.00 across 401 journal entries. In double-entry bookkeeping this cannot happen by accident, so every figure in this month\'s report should be treated as unsafe until the institution explains it.','{\"total_debits\":\"12480000.00\",\"total_credits\":\"11730000.00\",\"difference\":\"750000.00\",\"journal_entry_count\":401,\"unposted_count\":0}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(3,2,2,'2026-08',17,'unbalanced_ledger','critical','The ledger does not balance','For 2026-08, St Bede College Ashing reported debits of 12480000.00 against credits of 11480000.00 — a difference of 1000000.00 across 408 journal entries. In double-entry bookkeeping this cannot happen by accident, so every figure in this month\'s report should be treated as unsafe until the institution explains it.','{\"total_debits\":\"12480000.00\",\"total_credits\":\"11480000.00\",\"difference\":\"1000000.00\",\"journal_entry_count\":408,\"unposted_count\":0}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(4,2,2,'2026-09',18,'unbalanced_ledger','critical','The ledger does not balance','For 2026-09, St Bede College Ashing reported debits of 12480000.00 against credits of 11230000.00 — a difference of 1250000.00 across 415 journal entries. In double-entry bookkeeping this cannot happen by accident, so every figure in this month\'s report should be treated as unsafe until the institution explains it.','{\"total_debits\":\"12480000.00\",\"total_credits\":\"11230000.00\",\"difference\":\"1250000.00\",\"journal_entry_count\":415,\"unposted_count\":0}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(5,3,3,'2026-04',23,'collection_gap','high','Collection is 62% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-04, implying 8420000.00 in fees, but collected 5220400.00 — a shortfall of 3199600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"5220400.00\",\"shortfall\":\"3199600.00\",\"collection_rate\":\"0.6200\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(6,3,3,'2026-05',24,'collection_gap','high','Collection is 57% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-05, implying 8420000.00 in fees, but collected 4799400.00 — a shortfall of 3620600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"4799400.00\",\"shortfall\":\"3620600.00\",\"collection_rate\":\"0.5700\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:05','2026-09-09 17:26:05',1,'2026-09-09 16:26:05','2026-09-09 16:26:05'),(7,3,3,'2026-06',25,'collection_gap','high','Collection is 52% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-06, implying 8420000.00 in fees, but collected 4378400.00 — a shortfall of 4041600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"4378400.00\",\"shortfall\":\"4041600.00\",\"collection_rate\":\"0.5200\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:06','2026-09-09 17:26:06',1,'2026-09-09 16:26:06','2026-09-09 16:26:06'),(8,3,3,'2026-07',26,'collection_gap','high','Collection is 47% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-07, implying 8420000.00 in fees, but collected 3957400.00 — a shortfall of 4462600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"3957400.00\",\"shortfall\":\"4462600.00\",\"collection_rate\":\"0.4700\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:06','2026-09-09 17:26:06',1,'2026-09-09 16:26:06','2026-09-09 16:26:06'),(9,3,3,'2026-08',27,'collection_gap','high','Collection is 42% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-08, implying 8420000.00 in fees, but collected 3536400.00 — a shortfall of 4883600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"3536400.00\",\"shortfall\":\"4883600.00\",\"collection_rate\":\"0.4200\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:06','2026-09-09 17:26:06',1,'2026-09-09 16:26:06','2026-09-09 16:26:06'),(10,3,3,'2026-09',28,'collection_gap','high','Collection is 37% of what enrolment implies','Shisong Cardiac Centre Pharmacy reported 842 students for 2026-09, implying 8420000.00 in fees, but collected 3115400.00 — a shortfall of 5304600.00. This is only as good as the fee structure behind it: until the body pushes fee templates down, expected fees are the institution\'s own number, and this is a prompt to ask rather than evidence.','{\"enrolment\":842,\"expected_fees\":\"8420000.00\",\"collected\":\"3115400.00\",\"shortfall\":\"5304600.00\",\"collection_rate\":\"0.3700\",\"minimum_rate\":0.7,\"cash_share\":\"0.3100\"}','open',NULL,NULL,NULL,'2026-09-09 17:26:06','2026-09-09 17:26:06',1,'2026-09-09 16:26:06','2026-09-09 16:26:06'),(11,3,4,NULL,NULL,'not_reporting','high','Not reporting for 98 days','Nothing has been received from St Augustine\'s College Kumbo for 98 days; the threshold is 35. The last period received was 2026-05.','{\"days_silent\":98,\"threshold_days\":35,\"last_period_received\":\"2026-05\",\"last_report_at\":\"2026-06-02 23:59:59\",\"last_heartbeat_at\":null}','open',NULL,NULL,NULL,'2026-09-09 17:26:11','2026-09-09 17:26:11',1,'2026-09-09 16:26:11','2026-09-09 16:26:11'),(12,2,1,'2026-08',29,'final_restated','critical','A closed month was refiled','Catholic University of Bamenda reported 2026-08 as final on Sep 9, 2026, then refiled it on Sep 9, 2026 at sequence 2. The surplus is unchanged, so something was reclassified rather than re-valued. Both versions are retained and can be compared. A month that changes after it was closed is the shape a retro-edited ledger takes.','{\"period\":\"2026-08\",\"previous_sequence\":1,\"new_sequence\":2,\"previous_surplus\":\"-804440.00\",\"new_surplus\":\"-804440.00\",\"surplus_movement\":\"0.00\",\"previous_ledger_hash\":\"sha256:db6def7aceea83886f83a57c80d56b42a1d6f8a370d3d37a436247fb962853c0\",\"new_ledger_hash\":\"sha256:db6def7aceea83886f83a57c80d56b42a1d6f8a370d3d37a436247fb962853c0\",\"days_between\":0.008564814814814815}','open',NULL,NULL,NULL,'2026-09-09 17:38:19','2026-09-09 17:38:19',1,'2026-09-09 16:38:19','2026-09-09 16:38:19');
